import 'package:supabase_flutter/supabase_flutter.dart';
class QuickRidesService{QuickRidesService(this.client);final SupabaseClient client;User? get user=>client.auth.currentUser;Future<String> createRide({required String pickup,required String destination,required String service,double fare=0})async{final u=user;if(u==null)throw Exception('Please sign in first.');final r=await client.from('rides').insert({'rider_id':u.id,'pickup_text':pickup,'destination_text':destination,'service':service,'estimated_fare':fare}).select('id').single();return r['id'] as String;}Future<bool> acceptRide(String id)async=>await client.rpc('accept_ride',params:{'p_ride_id':id})==true;}
